#include "wokwi-api.h"
#include <stdbool.h>
#include <stdint.h>
#include <stddef.h>

/* Test instrument only. It drives the PIR input, not MCU code or storage.
   100 pulses, each exactly 20000 us high and 180200 us low. A 200200-us
   period advances by 200 us modulo a 20-ms release, covering all phases.
   First group begins at 1 s. Repeat groups every 25 s to allow a UART
   backlog to be started before a later group. Actual timing is verified
   from VCD; no detector result is generated by this model. */
static pin_t output;
static timer_t edge_timer;
static unsigned pulse;
static bool high;

static void next_edge(void *unused)
{
  (void)unused;
  if(high) {
    pin_write(output,LOW);high=false;
    ++pulse;
    timer_start(edge_timer,pulse==100?5160200:180200,false);
  } else {
    if(pulse==100)pulse=0;
    pin_write(output,HIGH);high=true;
    timer_start(edge_timer,20000,false);
  }
}

void chip_init(void)
{
  output=pin_init("OUT",OUTPUT_LOW);
  const timer_config_t config={.callback=next_edge,.user_data=NULL};
  edge_timer=timer_init(&config);
  timer_start(edge_timer,1000000,false);
}
